<?php
require_once __DIR__.'/../includes/auth.php';require_login();$bid=current_branch_id();$expiryDays=rule_int('expiry_warning_days',7);$equipmentDays=rule_int('equipment_warning_days',7);$retentionDays=rule_int('retention_days',14);$riskThreshold=rule_int('retention_visit_threshold',1);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE notifications SET is_read=1 WHERE branch_id=? AND (user_id IS NULL OR user_id=?)')->execute([$bid,user()['id']]);flash('success','Stored notifications marked as read.');redirect('app/notifications.php');}
$rows=query_all('SELECT * FROM notifications WHERE branch_id=? AND (user_id IS NULL OR user_id=?) ORDER BY created_at DESC LIMIT 50',[$bid,user()['id']]);
$role=user()['role']??'';$expiring=$equipment=$risk=0;
if($role==='trainer'){$tid=(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0);$expiring=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND trainer_id=? AND status='active' AND membership_end BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL $expiryDays DAY)",[$bid,$tid]);$risk=(int)query_value("SELECT COUNT(*) FROM (SELECT m.id,COUNT(a.id) v FROM members m LEFT JOIN attendance a ON a.member_id=m.id AND a.check_in>=DATE_SUB(NOW(),INTERVAL $retentionDays DAY) WHERE m.branch_id=? AND m.trainer_id=? AND m.status='active' AND m.membership_end>=CURDATE() GROUP BY m.id HAVING v<=$riskThreshold) x",[$bid,$tid]);}
elseif(in_array($role,['super_admin','manager','receptionist'])){$expiring=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND status='active' AND membership_end BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL $expiryDays DAY)",[$bid]);$risk=(int)query_value("SELECT COUNT(*) FROM (SELECT m.id,COUNT(a.id) v FROM members m LEFT JOIN attendance a ON a.member_id=m.id AND a.check_in>=DATE_SUB(NOW(),INTERVAL $retentionDays DAY) WHERE m.branch_id=? AND m.status='active' AND m.membership_end>=CURDATE() GROUP BY m.id HAVING v<=$riskThreshold) x",[$bid]);if(in_array($role,['super_admin','manager']))$equipment=(int)query_value("SELECT COUNT(*) FROM equipment WHERE branch_id=? AND condition_status<>'retired' AND (condition_status IN('maintenance','damaged') OR next_service<=DATE_ADD(CURDATE(),INTERVAL $equipmentDays DAY))",[$bid]);}
$alerts=[];if($expiring)$alerts[]=['warning','Membership renewal attention',"$expiring active membership(s) end within $expiryDays day(s).",'members.php'];if($equipment)$alerts[]=['warning','Equipment attention',"$equipment asset(s) need maintenance/service attention.",'equipment.php'];if($risk)$alerts[]=['danger','Retention attention',"$risk member(s) meet the configured at-risk attendance rule.",'dashboard.php'];
$pageTitle='Notifications';include __DIR__.'/../includes/header.php'; ?>
<?php if($alerts):?><div class="panel mb-3"><div class="panel-head"><div><h3>Live operational alerts</h3><p>Calculated now from your business rules and current database data</p></div></div><div class="mini-list"><?php foreach($alerts as [$type,$title,$msg,$link]):?><a class="mini-row" href="<?= url('app/'.$link) ?>"><div class="mini-avatar"><i class="fa-solid fa-triangle-exclamation"></i></div><div class="grow"><strong><?= e($title) ?></strong><small><?= e($msg) ?></small></div><span class="badge-soft badge-<?= e($type) ?>">Live</span></a><?php endforeach;?></div></div><?php endif;?>
<div class="page-actions"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><button class="btn btn-dark">Mark stored notifications as read</button></form></div><div class="panel"><div class="panel-head"><div><h3>Notification history</h3><p>Saved messages for your account</p></div></div><div class="mini-list"><?php foreach($rows as $n): ?><div class="mini-row" style="opacity:<?= $n['is_read']?'.65':'1' ?>"><div class="mini-avatar"><i class="fa-solid <?= $n['type']==='warning'?'fa-triangle-exclamation':($n['type']==='success'?'fa-circle-check':'fa-bell') ?>"></i></div><div class="grow"><strong><?= e($n['title']) ?></strong><small><?= e($n['message']) ?> · <?= format_date($n['created_at'],'d M, h:i A') ?></small></div><?php if(!$n['is_read']): ?><span class="badge-soft badge-info">New</span><?php endif; ?></div><?php endforeach; if(!$rows): ?><p class="text-muted small">No stored notifications yet.</p><?php endif; ?></div></div>
<?php include __DIR__.'/../includes/footer.php'; ?>